# =========================================================
# FORMATERING OG ROUTING
# =========================================================

def format_kr(value):
    return f"{value:,.0f}".replace(",", ".")


def format_number(value, decimals=1):
    text = f"{value:,.{decimals}f}"
    return text.replace(",", "X").replace(".", ",").replace("X", ".")


def clean_filename(value):
    value = (value or "Rockcycle_tilbud").strip()
    value = re.sub(r"[^A-Za-z0-9ÆØÅæøå_-]+", "_", value)
    return value.strip("_") or "Rockcycle_tilbud"


def format_day_list(days, lowercase=False):
    values = list(days or [])
    if lowercase:
        values = [day.lower() for day in values]

    if not values:
        return ""
    if len(values) == 1:
        return values[0]
    if len(values) == 2:
        return f"{values[0]} og {values[1]}"
    return f"{', '.join(values[:-1])} og {values[-1]}"


@st.cache_data(ttl=86400, show_spinner=False)
def geocode_project_address(address):
    query = address.strip()
    if "danmark" not in query.lower() and "denmark" not in query.lower():
        query = f"{query}, Danmark"

    response = requests.get(
        "https://nominatim.openstreetmap.org/search",
        params={
            "q": query,
            "format": "jsonv2",
            "limit": 1,
            "countrycodes": "dk",
        },
        headers={"User-Agent": "RockcycleOfferApp/4.9"},
        timeout=15,
    )
    response.raise_for_status()
    data = response.json()

    if not data:
        return None

    return {
        "lat": float(data[0]["lat"]),
        "lon": float(data[0]["lon"]),
        "display_name": data[0].get("display_name", address),
    }


@st.cache_data(ttl=3600, show_spinner=False)
def route_to_single(start_lat, start_lon, end_lat, end_lon):
    coordinates = f"{start_lon},{start_lat};{end_lon},{end_lat}"
    response = requests.get(
        f"https://router.project-osrm.org/route/v1/driving/{coordinates}",
        params={"overview": "false", "steps": "false", "alternatives": "false"},
        headers={"User-Agent": "RockcycleOfferApp/4.9"},
        timeout=20,
    )
    response.raise_for_status()
    data = response.json()

    if data.get("code") != "Ok" or not data.get("routes"):
        return None

    route = data["routes"][0]
    return {
        "distance_km": route["distance"] / 1000,
        "duration_min": route["duration"] / 60,
    }


@st.cache_data(ttl=3600, show_spinner=False)
def routes_to_demolition_facilities(start_lat, start_lon):
    points = [(start_lat, start_lon)] + [
        (facility["lat"], facility["lon"]) for facility in DEMOLITION_FACILITIES
    ]
    coordinate_string = ";".join(f"{lon},{lat}" for lat, lon in points)

    response = requests.get(
        f"https://router.project-osrm.org/table/v1/driving/{coordinate_string}",
        params={"sources": "0", "annotations": "duration,distance"},
        headers={"User-Agent": "RockcycleOfferApp/4.9"},
        timeout=30,
    )
    response.raise_for_status()
    data = response.json()

    if data.get("code") != "Ok":
        return []

    durations = data.get("durations", [[]])[0]
    distances = data.get("distances", [[]])[0]
    options = []

    for index, facility in enumerate(DEMOLITION_FACILITIES, start=1):
        duration_seconds = durations[index] if index < len(durations) else None
        distance_meters = distances[index] if index < len(distances) else None
        if duration_seconds is None or distance_meters is None:
            continue

        options.append(
            {
                "facility": facility,
                "duration_min": duration_seconds / 60,
                "distance_km": distance_meters / 1000,
            }
        )

    # Dropdown sorteres efter faktisk vejafstand, korteste først.
    return sorted(options, key=lambda item: item["distance_km"])


