def section_heading(number, title):
    st.markdown(
        f'<div class="section-title"><span class="section-number">{number}</span>{title}</div>',
        unsafe_allow_html=True,
    )


def render_quote(quote):
    st.markdown(
        f"""
        <div class="quote-card">
            <div class="quote-eyebrow">Estimeret pris pr. afhentning</div>
            <div class="quote-price">{format_kr(quote['price_per_pickup'])} kr.</div>
            <div class="quote-note">Prisen er pr. afhentning og inkluderer den valgte containerløsning, transport, afhentningsservice og relevant håndtering/gate fee.</div>
        </div>
        """,
        unsafe_allow_html=True,
    )

    st.subheader("Dit estimerede tilbud")

    st.markdown("#### Kunde og projekt")
    left, right = st.columns(2)
    with left:
        st.write(f"**Virksomhed:** {quote.get('company') or '-'}")
        st.write(f"**Kontaktperson:** {quote.get('contact_name') or '-'}")
        st.write(f"**E-mail:** {quote.get('email') or '-'}")
        st.write(f"**Telefon:** {quote.get('phone') or '-'}")
    with right:
        st.write(f"**Projekt:** {quote.get('project_name') or '-'}")
        st.write(f"**Projektadresse:** {quote['project_address']}")

    st.markdown("#### Løsning")
    left, right = st.columns(2)
    with left:
        st.write(f"**Materiale:** {quote['material_label']}")
        st.write(f"**Container:** Løsning {quote['container']}")
    with right:
        st.write(f"**Destination:** {quote['destination_label']}")
        st.write(f"**Afstand:** {format_number(quote['distance_km'], 1)} km")

    st.markdown("#### Afhentning")
    st.write(f"**Afhentningsform:** {quote.get('pickup_type', '-')}")
    if quote.get("pickup_type") == "Fast afhentning":
        pickup_days = quote.get("fixed_pickup_days", "").strip()
        pickups_per_week = quote.get("fixed_pickups_per_week", 0)
        st.write(
            f"**Frekvens:** {pickups_per_week} "
            f"{'gang' if pickups_per_week == 1 else 'gange'} pr. uge"
        )
        st.write(
            f"**Faste afhentningsdage:** "
            f"{pickup_days if pickup_days else 'Aftales ved accept af tilbud'}"
        )
    elif quote.get("pickup_type") == "Fleksibel afhentning":
        st.write(
            "Afhentning bestilles via QR-kode. Containeren afhentes inden for 24 timer efter bestilling."
        )

    if quote["material_kind"] == "offcut":
        st.markdown("#### Estimeret returflow")
        a, b, c = st.columns(3)
        a.metric("ROCKWOOL på projektet", f"{format_number(quote['new_wool_tons'], 1)} ton")
        b.metric("Estimeret fraskær", f"{format_number(quote['estimated_offcut_kg'], 0)} kg")
        c.metric("Estimerede afhentninger", str(quote["estimated_pickups"]))

        st.info(
            f"Med de angivne mængder og containerløsning {quote['container']} estimerer vi ca. "
            f"**{quote['estimated_pickups']} afhentning(er)**. Den viste pris på "
            f"**{format_kr(quote['price_per_pickup'])} kr. er pr. afhentning**."
        )

    st.markdown("#### Pris pr. afhentning")
    st.write(
        f"**Transport til {quote['destination_label']} ({format_number(quote['distance_km'], 1)} km):** "
        f"{format_kr(quote['transport_price'])} kr."
    )
    st.write(
        f"**Containerløsning {quote['container']}:** {format_kr(quote['container_price'])} kr."
    )
    st.write(
        f"**Afhentningsservice ({quote.get('pickup_type', '-')}):** "
        f"{format_kr(quote.get('pickup_fee', 0))} kr."
    )
    st.write(f"**{quote['handling_label']}:** {format_kr(quote['handling_fee'])} kr.")

    st.markdown(
        '<div class="mini-note">Transporten er beregnet én vej til den valgte destination. '
        'Returkørsel, ventetid og øvrige tillæg er ikke inkluderet i estimatet.</div>',
        unsafe_allow_html=True,
    )

    try:
        pdf_bytes = create_quote_pdf(quote)
        filename = f"Rockcycle_tilbud_{clean_filename(quote.get('project_name'))}.pdf"
        st.download_button(
            "Download tilbud som PDF",
            data=pdf_bytes,
            file_name=filename,
            mime="application/pdf",
            use_container_width=False,
        )
    except RuntimeError as exc:
        st.warning(str(exc))



def set_exclusive_choice(chosen_key, all_keys):
    """Keep exactly one option selected in a checkbox-based single-choice group."""
    if st.session_state.get(chosen_key):
        for key in all_keys:
            if key != chosen_key:
                st.session_state[key] = False
    else:
        # Do not allow the group to end with no selected option.
        if not any(st.session_state.get(key, False) for key in all_keys):
            st.session_state[chosen_key] = True


def selected_key(keys, fallback):
    for key in keys:
        if st.session_state.get(key, False):
            return key
    return fallback


def enforce_pickup_day_limit():
    """Prevent selecting more weekdays than the chosen weekly frequency."""
    limit = int(st.session_state.get("fixed_pickups_per_week", 1))
    current = list(st.session_state.get("fixed_pickup_days", []) or [])
    previous = list(st.session_state.get("_previous_fixed_pickup_days", []) or [])

    if len(current) > limit:
        st.session_state["fixed_pickup_days"] = previous[:limit]
    else:
        st.session_state["_previous_fixed_pickup_days"] = current


def sync_pickup_days_to_frequency():
    """Trim selected weekdays if the weekly frequency is reduced."""
    limit = int(st.session_state.get("fixed_pickups_per_week", 1))
    current = list(st.session_state.get("fixed_pickup_days", []) or [])

    if len(current) > limit:
        current = current[:limit]
        st.session_state["fixed_pickup_days"] = current

    st.session_state["_previous_fixed_pickup_days"] = current


def main():
    st.set_page_config(
        page_title="Rockcycle - Opret dit projekt",
        page_icon=Image.open(io.BytesIO(base64.b64decode(ROCKCYCLE_TAB_ICON_B64))),
        layout="wide",
    )
    inject_css()

    st.markdown(
        f"""
        <div class="rw-header">
            <img class="rw-logo" src="data:image/jpeg;base64,{LOGO_B64}" alt="ROCKWOOL logo">
        </div>
        <div class="rw-intro">
            <div class="rw-kicker">Rockcycle® returordning</div>
            <div class="rw-main-title">Opret dit projekt og få et estimeret tilbud</div>
            <p>Indtast projektets oplysninger, vælg returmateriale og containerløsning. Systemet beregner derefter en estimeret pris pr. afhentning.</p>
        </div>
        """,
        unsafe_allow_html=True,
    )

    section_heading(1, "Kontakt- og projektoplysninger")
    col1, col2 = st.columns(2)
    with col1:
        company = st.text_input("Virksomhed")
        contact_name = st.text_input("Kontaktperson")
        email = st.text_input("E-mail")
        phone = st.text_input("Telefonnummer")
    with col2:
        project_name = st.text_input("Projektnavn")
        project_address = st.text_input(
            "Projektadresse *",
            placeholder="Fx Roskildevej 22, 2620 Albertslund",
        )

    normalized_address = project_address.strip()

    section_heading(2, "Returmateriale")
    material_type = st.radio(
        "Hvilken type stenuld skal returneres?",
        [
            "Nyt stenuld / fraskær",
            "Brugt stenuld fra renovering eller nedrivning",
        ],
        horizontal=True,
    )

    new_wool_tons = None
    if material_type == "Nyt stenuld / fraskær":
        new_wool_tons = st.number_input(
            "Mængde ROCKWOOL købt til projektet (ton)",
            min_value=0.0,
            step=1.0,
            format="%.1f",
            help="Angiv den samlede købte mængde i ton. Fraskær estimeres som 10 % af denne mængde.",
        )

    section_heading(3, "Containerløsning")
    st.write("Vælg den containerløsning, der passer bedst til projektet.")

    if material_type == "Nyt stenuld / fraskær":
        container_labels = {
            key: (
                f"Løsning {key} · ca. {CONTAINERS[key]['capacity_kg']} kg · "
                f"{format_kr(CONTAINERS[key]['price'])} kr. pr. afhentning"
            )
            for key in CONTAINERS
        }
    else:
        container_labels = {
            key: (
                f"Løsning {key} · {format_kr(CONTAINERS[key]['price'])} kr. pr. afhentning"
            )
            for key in CONTAINERS
        }

    # Initialise the single-choice group.
    container_keys = ["container_x", "container_y", "container_z"]
    if not any(key in st.session_state for key in container_keys):
        st.session_state["container_x"] = True
        st.session_state["container_y"] = False
        st.session_state["container_z"] = False

    container_rows = [
        ("X", "container_x", "Vi anbefaler denne løsning til ..."),
        ("Y", "container_y", "Vi anbefaler denne løsning til ..."),
        ("Z", "container_z", "Vi anbefaler denne løsning til ..."),
    ]

    for option_key, state_key, info_text in container_rows:
        option_col, info_col, spacer_col = st.columns([0.34, 0.035, 0.625], gap="small")
        with option_col:
            st.checkbox(
                container_labels[option_key],
                key=state_key,
                on_change=set_exclusive_choice,
                args=(state_key, container_keys),
            )
        with info_col:
            with st.popover("ⓘ"):
                st.write(info_text)

    container_state = selected_key(container_keys, "container_x")
    container = {
        "container_x": "X",
        "container_y": "Y",
        "container_z": "Z",
    }[container_state]

    container_data = CONTAINERS[container]
    st.caption("Én container svarer til én afhentning.")

    section_heading(4, "Afhentningsfrekvens")
    st.write("Vælg hvordan I ønsker, at containeren skal afhentes.")

    pickup_keys = ["pickup_fixed", "pickup_flexible"]
    if not any(key in st.session_state for key in pickup_keys):
        st.session_state["pickup_fixed"] = True
        st.session_state["pickup_flexible"] = False

    pickup_rows = [
        (
            "Fast afhentning",
            "pickup_fixed",
            "Fast afhentning betyder, at affaldet hentes på en eller flere faste dage om ugen. "
            "De faste afhentningsdage fastsættes, når Rockcycle-tilbuddet accepteres.",
        ),
        (
            "Fleksibel afhentning",
            "pickup_flexible",
            "Ved fleksibel afhentning udstyres byggepladsen med en QR-kode, som kan scannes "
            "for at bestille afhentning. Containeren afhentes inden for 24 timer efter bestilling.",
        ),
    ]

    for label, state_key, info_text in pickup_rows:
        option_col, info_col, spacer_col = st.columns([0.19, 0.035, 0.775], gap="small")
        with option_col:
            st.checkbox(
                label,
                key=state_key,
                on_change=set_exclusive_choice,
                args=(state_key, pickup_keys),
            )
        with info_col:
            with st.popover("ⓘ"):
                st.write(info_text)

    pickup_state = selected_key(pickup_keys, "pickup_fixed")
    pickup_type = {
        "pickup_fixed": "Fast afhentning",
        "pickup_flexible": "Fleksibel afhentning",
    }[pickup_state]

    fixed_pickups_per_week = 0
    selected_pickup_days = []
    fixed_pickup_days = ""
    fixed_schedule_valid = True

    if pickup_type == "Fast afhentning":
        frequency_col, frequency_spacer = st.columns([0.28, 0.72])
        with frequency_col:
            fixed_pickups_per_week = st.selectbox(
                "Afhentninger pr. uge",
                options=[1, 2, 3, 4, 5],
                index=0,
                format_func=lambda n: f"{n} gang" if n == 1 else f"{n} gange",
                key="fixed_pickups_per_week",
                on_change=sync_pickup_days_to_frequency,
            )

        if "_previous_fixed_pickup_days" not in st.session_state:
            st.session_state["_previous_fixed_pickup_days"] = list(
                st.session_state.get("fixed_pickup_days", []) or []
            )

        selected_pickup_days = st.pills(
            "Vælg ønskede afhentningsdage",
            ["Mandag", "Tirsdag", "Onsdag", "Torsdag", "Fredag"],
            selection_mode="multi",
            key="fixed_pickup_days",
            width="content",
            on_change=enforce_pickup_day_limit,
        ) or []

        fixed_schedule_valid = len(selected_pickup_days) == fixed_pickups_per_week
        fixed_pickup_days = format_day_list(selected_pickup_days)

        if fixed_schedule_valid:
            st.markdown(
                f"**Du har valgt {fixed_pickups_per_week} "
                f"{'fast afhentning' if fixed_pickups_per_week == 1 else 'faste afhentninger'} "
                f"pr. uge: {format_day_list(selected_pickup_days, lowercase=True)}.**"
            )
        else:
            missing = fixed_pickups_per_week - len(selected_pickup_days)
            st.warning(
                f"Vælg {missing} {'dag' if missing == 1 else 'dage'} mere."
            )

    pickup_fee = (
        FIXED_PICKUP_FEE
        if pickup_type == "Fast afhentning"
        else FLEXIBLE_PICKUP_FEE
    )

    selected_demolition_option = None

    if material_type == "Brugt stenuld fra renovering eller nedrivning":
        section_heading(5, "Vælg modtageanlæg")
        st.write(
            "Vælg et modtageanlæg. Vi anbefaler at anvende det nærmeste anlæg."
        )

        # Dropdownen er altid synlig. Hvis der ikke er en projektadresse endnu,
        # vises blot en tydelig besked i feltet.
        if not normalized_address:
            st.selectbox(
                "Vælg modtageanlæg",
                ["Projektadresse mangler"],
                index=0,
                disabled=True,
                key="facility_missing_address",
            )
        else:
            try:
                with st.spinner("Beregner afstande til modtageanlæg..."):
                    project_coords = geocode_project_address(normalized_address)

                    if project_coords is None:
                        st.selectbox(
                            "Vælg modtageanlæg",
                            ["Projektadressen kunne ikke findes"],
                            index=0,
                            disabled=True,
                            key="facility_invalid_address",
                        )
                    else:
                        options = routes_to_demolition_facilities(
                            project_coords["lat"], project_coords["lon"]
                        )

                        if not options:
                            st.selectbox(
                                "Vælg modtageanlæg",
                                ["Kunne ikke beregne afstande til modtageanlæg"],
                                index=0,
                                disabled=True,
                                key="facility_no_routes",
                            )
                        else:
                            labels = [
                                f"{item['facility']['company']} - {item['facility']['name']} · "
                                f"{format_number(item['distance_km'], 1)} km"
                                for item in options
                            ]

                            selected_label = st.selectbox(
                                "Vælg modtageanlæg",
                                labels,
                                index=0,
                                key="facility_select",
                            )

                            selected_demolition_option = options[
                                labels.index(selected_label)
                            ]
                            facility = selected_demolition_option["facility"]
                            st.caption(f"{facility['address']}")

            except requests.RequestException:
                st.selectbox(
                    "Vælg modtageanlæg",
                    ["Korttjenesten kunne ikke kontaktes"],
                    index=0,
                    disabled=True,
                    key="facility_service_error",
                )
    else:
        section_heading(5, "Direkte til genanvendelse")
        st.write(
            "Rent fraskær skal holdes **rent og tørt** og returneres direkte til genanvendelse "
            "på **ROCKWOOLs fabrik i Vamdrup**."
        )
        st.caption(
            f"{VAMDRUP['address']} · Gate fee: {format_kr(OFFCUT_GATE_FEE)} kr. pr. afhentning"
        )

    # Keep the displayed offer synchronized with the current form.
    selected_facility_id = ""
    if selected_demolition_option is not None:
        _facility = selected_demolition_option["facility"]
        selected_facility_id = f"{_facility['company']}|{_facility['name']}|{_facility['address']}"

    current_form_signature = (
        company.strip(),
        contact_name.strip(),
        email.strip(),
        phone.strip(),
        project_name.strip(),
        normalized_address,
        material_type,
        float(new_wool_tons or 0),
        container,
        pickup_type,
        fixed_pickups_per_week,
        tuple(selected_pickup_days),
        selected_facility_id,
    )

    existing_quote = st.session_state.get("quote")
    if (
        existing_quote is not None
        and existing_quote.get("_form_signature") != current_form_signature
    ):
        st.session_state.pop("quote", None)

    st.divider()

    quote_button_disabled = (
        pickup_type == "Fast afhentning" and not fixed_schedule_valid
    )

    if st.button(
        "Giv mig et tilbud",
        type="primary",
        use_container_width=True,
        disabled=quote_button_disabled,
    ):
        st.session_state.pop("quote", None)

        if not normalized_address:
            st.error("Indtast projektadressen, før tilbuddet beregnes.")
            st.stop()

        if pickup_type == "Fast afhentning" and not fixed_schedule_valid:
            st.error(
                f"Vælg præcis {fixed_pickups_per_week} "
                f"{'afhentningsdag' if fixed_pickups_per_week == 1 else 'afhentningsdage'}."
            )
            st.stop()

        if material_type == "Nyt stenuld / fraskær" and (new_wool_tons is None or new_wool_tons <= 0):
            st.error("Angiv hvor mange ton ROCKWOOL der er købt til projektet.")
            st.stop()

        if material_type == "Brugt stenuld fra renovering eller nedrivning" and selected_demolition_option is None:
            st.error("Vælg et modtageanlæg, før tilbuddet beregnes.")
            st.stop()

        try:
            with st.spinner("Beregner dit estimerede tilbud..."):
                project_coords = geocode_project_address(normalized_address)
                if project_coords is None:
                    st.error("Projektadressen kunne ikke findes.")
                    st.stop()

                if material_type == "Nyt stenuld / fraskær":
                    route = route_to_single(
                        project_coords["lat"], project_coords["lon"], VAMDRUP["lat"], VAMDRUP["lon"]
                    )
                    if route is None:
                        st.error("Ruten til ROCKWOOL Vamdrup kunne ikke beregnes.")
                        st.stop()

                    estimated_offcut_kg = new_wool_tons * 1000 * OFFCUT_PERCENTAGE
                    estimated_pickups = math.ceil(estimated_offcut_kg / container_data["capacity_kg"])
                    transport_price = (route["duration_min"] / 60) * TRANSPORT_RATE_PER_HOUR
                    price_per_pickup = transport_price + container_data["price"] + OFFCUT_GATE_FEE + pickup_fee

                    quote = {
                        "date": datetime.now().strftime("%d.%m.%Y"),
                        "company": company,
                        "contact_name": contact_name,
                        "email": email,
                        "phone": phone,
                        "project_name": project_name,
                        "project_address": normalized_address,
                        "material_kind": "offcut",
                        "material_label": "Nyt stenuld / fraskær",
                        "new_wool_tons": new_wool_tons,
                        "estimated_offcut_kg": estimated_offcut_kg,
                        "estimated_pickups": estimated_pickups,
                        "container": container,
                        "container_capacity_kg": container_data["capacity_kg"],
                        "container_price": container_data["price"],
                        "pickup_type": pickup_type,
                        "fixed_pickups_per_week": fixed_pickups_per_week,
                        "fixed_pickup_days": fixed_pickup_days,
                        "pickup_fee": pickup_fee,
                        "distance_km": route["distance_km"],
                        "transport_price": transport_price,
                        "handling_fee": OFFCUT_GATE_FEE,
                        "handling_label": "Gate fee i Vamdrup",
                        "destination_label": "ROCKWOOL Vamdrup",
                        "price_per_pickup": price_per_pickup,
                        "_form_signature": current_form_signature,
                    }

                else:
                    selected = selected_demolition_option
                    facility = selected["facility"]
                    transport_price = (selected["duration_min"] / 60) * TRANSPORT_RATE_PER_HOUR
                    price_per_pickup = transport_price + container_data["price"] + DEMOLITION_GATE_FEE + pickup_fee

                    quote = {
                        "date": datetime.now().strftime("%d.%m.%Y"),
                        "company": company,
                        "contact_name": contact_name,
                        "email": email,
                        "phone": phone,
                        "project_name": project_name,
                        "project_address": normalized_address,
                        "material_kind": "demolition",
                        "material_label": "Brugt stenuld fra renovering eller nedrivning",
                        "container": container,
                        "container_capacity_kg": container_data["capacity_kg"],
                        "container_price": container_data["price"],
                        "pickup_type": pickup_type,
                        "fixed_pickups_per_week": fixed_pickups_per_week,
                        "fixed_pickup_days": fixed_pickup_days,
                        "pickup_fee": pickup_fee,
                        "distance_km": selected["distance_km"],
                        "transport_price": transport_price,
                        "handling_fee": DEMOLITION_GATE_FEE,
                        "handling_label": "Gate fee / håndtering",
                        "destination_label": f"{facility['company']} - {facility['name']}",
                        "facility_company": facility["company"],
                        "facility_name": facility["name"],
                        "facility_address": facility["address"],
                        "price_per_pickup": price_per_pickup,
                        "_form_signature": current_form_signature,
                    }

                st.session_state["quote"] = quote

        except requests.RequestException:
            st.error("Korttjenesten kunne ikke kontaktes. Kontrollér internetforbindelsen og prøv igen.")

    quote = st.session_state.get("quote")
    if quote:
        st.divider()
        render_quote(quote)


if __name__ == "__main__":
    main()
